#!/usr/bin/env bash
# Remove files generated by a demo run, so the next run starts clean.
# Keeps the source code (.py, .c) and the compiled victim.
set -e
rm -f messages.txt ciphertexts.txt traces.csv \
      public_key.txt secret_key.txt recovered_key.txt timing_plot.png
rm -rf __pycache__
echo "flushed: messages / ciphertexts / traces / keys / recovered / plot"
echo "kept   : source files and compiled 'victim'"
